CREATE FUNCTION dg_native_bill_transport_record(table_value text,operation_value text,j jsonb,previous jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE record_value text;bill_value text;operation_id_value text;b restaurant_bills%ROWTYPE;actual_action _dg_native_dining_actions%ROWTYPE;mutable_fields text[];
BEGIN
 IF table_value NOT IN('restaurant_bills','restaurant_financial_operations','restaurant_financial_receipts','restaurant_financial_postings','restaurant_financial_events','mock_financial_operations') THEN RETURN false;END IF;
 record_value:=CASE WHEN table_value='restaurant_financial_receipts' THEN j->>'event_id' WHEN table_value='mock_financial_operations' THEN j->>'operation_id' ELSE j->>'id' END;
 operation_id_value:=CASE WHEN table_value='restaurant_financial_operations' THEN j->>'id' WHEN table_value IN('restaurant_financial_receipts','restaurant_financial_postings','mock_financial_operations') THEN j->>'operation_id' END;
 bill_value:=CASE WHEN table_value='restaurant_bills' THEN j->>'id' WHEN table_value='restaurant_financial_events' THEN j->>'bill_id' ELSE(SELECT bill_id FROM restaurant_financial_operations WHERE id=operation_id_value) END;SELECT * INTO b FROM restaurant_bills WHERE id=bill_value;
 SELECT actual.* INTO actual_action FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions actual ON actual.id=effect.action_id WHERE effect.table_name=table_value AND effect.resource_id=record_value AND effect.transaction_id=pg_current_xact_id()::text AND actual.transaction_id=effect.transaction_id AND actual.restaurant_id=b.restaurant_id AND actual.resource_id=b.party_id AND actual.kind IN('bill_action','bill_fixture','bill_send','bill_query','bill_close','bill_simulate','bill_unknown','bill_stale','bill_action_blocked','bill_mock','bill_receipt','order_receipt') ORDER BY actual.created_at DESC,actual.id DESC LIMIT 1;
 IF actual_action.id IS NULL THEN RETURN false;END IF;IF operation_value='DELETE' OR NOT dg_native_dining_changed(table_value,record_value) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial history requires its exact scoped durable operation';END IF;
 IF table_value='restaurant_financial_operations' THEN
  mutable_fields:=ARRAY['status','version','send_attempts','simulate_attempts','lookups','last_lookup_at','next_action','action_actor_id','action_session_id','action_focus_version','action_party_access_version','lease_action','lease_token','lease_until','remote_operation_id','remote_transaction_id','last_sequence','error_code','error_message','updated_at'];
  IF operation_value<>'UPDATE' OR j-mutable_fields IS DISTINCT FROM previous-mutable_fields OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR j->>'updated_at'<>actual_action.created_at OR(j->>'send_attempts')::bigint NOT BETWEEN 0 AND 1 OR(j->>'simulate_attempts')::bigint NOT BETWEEN 0 AND 1 OR(j->>'send_attempts')::bigint<(previous->>'send_attempts')::bigint OR(j->>'simulate_attempts')::bigint<(previous->>'simulate_attempts')::bigint OR(j->>'lookups')::bigint<(previous->>'lookups')::bigint OR(j->>'last_sequence')::bigint<(previous->>'last_sequence')::bigint THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial transport preserves immutable request, actor, amount and monotone attempts';END IF;
  IF(j->>'send_attempts')::bigint>(previous->>'send_attempts')::bigint AND(actual_action.kind<>'bill_send' OR previous->>'status'<>'queued' OR(previous->>'send_attempts')::bigint<>0) OR(j->>'simulate_attempts')::bigint>(previous->>'simulate_attempts')::bigint AND(actual_action.kind<>'bill_simulate' OR previous->>'status'<>'pending' OR(previous->>'simulate_attempts')::bigint<>0) OR(j->>'lookups')::bigint>(previous->>'lookups')::bigint AND actual_action.kind<>'bill_query' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Sending, explicit simulation and original lookup each retain their actual single attempt';END IF;
  IF j->>'remote_operation_id' IS NOT NULL AND j->>'remote_operation_id' IS DISTINCT FROM(CASE WHEN j->>'kind'='payment' THEN 'mock-pay:' ELSE 'mock-refund:' END)||record_value OR j->>'remote_transaction_id' IS NOT NULL AND j->>'remote_transaction_id' IS DISTINCT FROM(CASE WHEN j->>'kind'='payment' THEN 'mock-charge:' ELSE 'mock-refund-tx:' END)||record_value OR previous->>'remote_operation_id' IS NOT NULL AND j->>'remote_operation_id' IS DISTINCT FROM previous->>'remote_operation_id' OR previous->>'remote_transaction_id' IS NOT NULL AND j->>'remote_transaction_id' IS DISTINCT FROM previous->>'remote_transaction_id' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Remote money identities remain the exact original operation';END IF;
  IF actual_action.kind='bill_action' AND j-ARRAY['next_action','action_actor_id','action_session_id','action_focus_version','action_party_access_version','version','updated_at'] IS DISTINCT FROM previous-ARRAY['next_action','action_actor_id','action_session_id','action_focus_version','action_party_access_version','version','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='A human request schedules only the original action and cannot fabricate funds';END IF;
  IF previous->>'error_code'='FINANCIAL_RECONCILIATION_REQUIRED' AND j->>'error_code' IS DISTINCT FROM 'FINANCIAL_RECONCILIATION_REQUIRED' AND NOT(actual_action.kind='bill_receipt' AND EXISTS(SELECT 1 FROM _dg_native_bill_receipt_origins origin JOIN restaurant_financial_receipts receipt ON receipt.event_id=origin.event_id WHERE origin.action_id=actual_action.id AND receipt.operation_id=record_value AND receipt.status='succeeded')) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Only a fresh verified success can repair a failed money projection';END IF;
  IF j->>'status'='succeeded' AND NOT EXISTS(SELECT 1 FROM restaurant_financial_postings WHERE operation_id=record_value) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Success requires a separate verified immutable posting';END IF;
 ELSIF table_value='restaurant_bills' THEN
  IF operation_value<>'UPDATE' OR j-ARRAY['version','status','attention_reason','settled_at','updated_at'] IS DISTINCT FROM previous-ARRAY['version','status','attention_reason','settled_at','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR j->>'updated_at'<>actual_action.created_at OR previous->>'settled_at' IS NOT NULL AND j->>'settled_at' IS DISTINCT FROM previous->>'settled_at' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Money transport cannot rewrite bill prices, identity or original settlement time';END IF;
 ELSIF table_value='restaurant_financial_postings' THEN
  IF operation_value<>'INSERT' OR actual_action.kind<>'bill_receipt' OR j->>'created_at'<>actual_action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Funds facts are append only and require a verified receipt';END IF;
 ELSIF table_value='restaurant_financial_receipts' THEN
  IF actual_action.kind<>'bill_receipt' OR(operation_value='INSERT' AND((j->>'applied')::bigint<>0 OR(j->>'attention')::bigint<>0 OR j->>'created_at'<>actual_action.created_at)) OR(operation_value='UPDATE' AND(j-ARRAY['applied','attention'] IS DISTINCT FROM previous-ARRAY['applied','attention'] OR(previous->>'applied')::bigint<>0 OR(previous->>'attention')::bigint<>0 OR(j->>'applied')::bigint+(j->>'attention')::bigint<>1)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receipt content is immutable and its single application result is retained';END IF;
 ELSIF table_value='mock_financial_operations' THEN
  IF actual_action.kind NOT IN('bill_mock','bill_fixture') OR j->>'updated_at'<>actual_action.created_at OR operation_value='UPDATE' AND(j-ARRAY['status','sequence','updated_at'] IS DISTINCT FROM previous-ARRAY['status','sequence','updated_at'] OR previous->>'status'<>'pending' OR(j->>'sequence')::bigint<=(previous->>'sequence')::bigint) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Mock remote facts retain original payload and monotone pending to final transitions';END IF;
 ELSE
  IF operation_value<>'INSERT' OR j->>'kind'<>actual_action.kind OR j->>'actor_id'<>actual_action.actor_id OR j->>'created_at'<>actual_action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial events retain their actual scoped actor and action';END IF;
 END IF;RETURN true;
END;$dg$;

CREATE FUNCTION dg_native_bill_transport_revision() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j jsonb:=to_jsonb(NEW);record_value text;actual_action _dg_native_dining_actions%ROWTYPE;revision_value bigint;
BEGIN
 record_value:=CASE WHEN TG_TABLE_NAME='restaurant_financial_receipts' THEN j->>'event_id' WHEN TG_TABLE_NAME='mock_financial_operations' THEN j->>'operation_id' ELSE j->>'id' END;SELECT actual.* INTO actual_action FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions actual ON actual.id=effect.action_id WHERE effect.table_name=TG_TABLE_NAME AND effect.resource_id=record_value AND effect.transaction_id=pg_current_xact_id()::text AND actual.transaction_id=effect.transaction_id ORDER BY actual.created_at DESC,actual.id DESC LIMIT 1;
 IF actual_action.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Financial row revisions retain their actual effect';END IF;
 IF TG_TABLE_NAME='restaurant_financial_operations' THEN INSERT INTO _dg_native_bill_operation_revisions VALUES(record_value,(j->>'version')::bigint,actual_action.id,dg_native_office_hash(j),j->>'updated_at');
 ELSIF TG_TABLE_NAME='mock_financial_operations' THEN INSERT INTO _dg_native_bill_mock_revisions VALUES(record_value,(j->>'sequence')::bigint,actual_action.id,dg_native_office_hash(j),j->>'updated_at');
 ELSE SELECT coalesce(max(revision),0)+1 INTO revision_value FROM _dg_native_bill_receipt_revisions WHERE event_id=record_value;INSERT INTO _dg_native_bill_receipt_revisions VALUES(record_value,revision_value,actual_action.id,dg_native_office_hash(j),actual_action.created_at);END IF;RETURN NEW;
END;$dg$;
DO $bill_transport_revisions$ DECLARE table_value text;BEGIN FOREACH table_value IN ARRAY ARRAY['restaurant_financial_operations','restaurant_financial_receipts','mock_financial_operations'] LOOP EXECUTE format('CREATE TRIGGER native_bill_transport_revision AFTER INSERT OR UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION dg_native_bill_transport_revision()',table_value);END LOOP;END;$bill_transport_revisions$;
